<script setup>
import { computed,reactive,ref } from 'vue'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import VesselFields from './VesselFields.vue'
import { display,numberOrNull } from './fields.js'
const store=useDemo(),search=ref(''),editing=ref(false),error=ref(''),pending=ref(null),model=reactive({})
const user=computed(()=>store.currentUser.value)
const rows=computed(()=>store.state.vessels.filter(v=>(user.value?.scope==='all'||(user.value?.scope==='office'?v.officeId===user.value.officeId:v.ownerId===user.value?.id))&&`${v.name} ${v.officialNumber} ${v.imoNumber} ${v.formerNames||''}`.toLowerCase().includes(search.value.toLowerCase())))
const offices=computed(()=>store.state.offices.filter(o=>o.active!==false).map(o=>({label:`${o.code} · ${o.name}`,value:o.id})))
const columns=[{name:'name',label:'Vessel',field:'name',align:'left',sortable:true},{name:'officialNumber',label:'Official / IMO no.',field:'officialNumber',align:'left'},{name:'type',label:'Service type',field:'type',align:'left',sortable:true},{name:'grossTonnage',label:'GT',field:v=>v.grossTonnage,align:'right',sortable:true},{name:'registrationStatus',label:'Registration',field:'registrationStatus',align:'left'},{name:'actions',label:'',field:'id'}]
function open(vessel){Object.keys(model).forEach(k=>delete model[k]);Object.assign(model,JSON.parse(JSON.stringify(vessel||{...store.newVessel(),ownerId:user.value.id,officeId:user.value.officeId})));error.value='';editing.value=true}
function save(){try{if(!model.name?.trim())throw Error('Enter the vessel name.');const data={...model,ownerId:model.ownerId||user.value.id,officeId:model.officeId||user.value.officeId};for(const key of ['grossTonnage','netTonnage','yearBuilt','length','breadth','depth','deadweight','engineCount','enginePower']){data[key]=numberOrNull(data[key]);if(data[key]!==null&&(!Number.isFinite(data[key])||data[key]<0))throw Error('Tonnage, dimensions and engine particulars must be non-negative numbers.')}if(model.id&&store.state.vessels.some(v=>v.id===model.id))store.update('vessels',model.id,data);else store.add('vessels',data);editing.value=false;error.value=''}catch(e){error.value=e.message}}
function remove(){try{store.remove('vessels',pending.value.id);pending.value=null;error.value=''}catch(e){error.value=e.message;pending.value=null}}
function involvements(id){return store.visibleEvents.value.filter(e=>e.vessels.some(v=>v.id===id)).length}
</script>
<template><div class="page-wrap"><PageHeader title="My vessel directory" subtitle="Maintain your account’s vessel particulars. Incident reports retain the particulars supplied when the vessel was added."><template #actions><q-btn v-if="store.can('report')" color="primary" icon="add" no-caps label="Add vessel" @click="open()"/></template></PageHeader><q-banner v-if="error&&!editing" class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}</q-banner><section class="panel"><div class="toolbar-row"><q-input v-model="search" outlined dense clearable label="Search vessel or identifier" @clear="search=''"/><q-space/><span class="muted">{{rows.length}} account vessel(s)</span></div><q-table :rows="rows" :columns="columns" row-key="id" flat :pagination="{rowsPerPage:10,sortBy:'name'}" wrap-cells><template #body-cell-name="p"><q-td :props="p"><q-btn flat no-caps color="primary" :label="p.row.name" @click="open(p.row)"/><div class="text-caption muted">{{involvements(p.row.id)}} linked incident(s)</div></q-td></template><template #body-cell-officialNumber="p"><q-td :props="p">{{p.row.officialNumber||'Not supplied'}}<div class="text-caption muted">IMO {{p.row.imoNumber||'not supplied'}}</div></q-td></template><template #body-cell-grossTonnage="p"><q-td :props="p">{{display(p.row.grossTonnage)}}</q-td></template><template #body-cell-actions="p"><q-td :props="p"><q-btn flat no-caps color="primary" label="View / edit" @click="open(p.row)"/><q-btn flat round icon="delete_outline" color="negative" aria-label="Remove directory vessel" @click="pending=p.row"/></q-td></template><template #no-data><div class="empty-state full-width"><q-icon name="directions_boat" size="40px"/><p>{{search?'No vessels match this search.':'No vessels in your directory. Add a vessel to reuse its particulars in reports.'}}</p></div></template></q-table></section><q-dialog v-model="editing" persistent><q-card style="width:900px;max-width:96vw"><q-card-section class="row items-center"><strong class="text-h6">{{model.name||'New vessel'}}</strong><q-space/><q-btn flat round icon="close" aria-label="Close vessel editor" v-close-popup/></q-card-section><q-card-section style="max-height:70vh;overflow:auto"><q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" role="alert">{{error}}</q-banner><VesselFields :model="model" :offices="offices" compact/><p class="muted q-mt-md">Directory updates apply to future report snapshots. Existing incident particulars stay attributed to their original report.</p></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn color="primary" no-caps label="Save vessel" @click="save"/></q-card-actions></q-card></q-dialog><q-dialog :model-value="!!pending" @update:model-value="pending=null"><q-card style="max-width:440px"><q-card-section class="text-h6">Remove directory vessel?</q-card-section><q-card-section>{{pending?.name}} will be removed from your reusable directory. Existing incident snapshots remain available.</q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn color="negative" no-caps label="Remove vessel" @click="remove"/></q-card-actions></q-card></q-dialog></div></template>
